"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$root = '"'E:\\codex-LOOP\\codex-loop-s-f2'
"'$repairs = Join-Path $root '"'data\\repairs'
function Test-JsonUtf8("'$path) {
  $text = Get-Content -LiteralPath $path -Encoding UTF8 -Raw
  try { $null = $text | ConvertFrom-Json; return '"'OK' } catch { return 'FAIL' }
}
foreach ("'$d in @('"'parent-replay-incident-20260813-044825','plain-parent-reports-20260813-045304','parent-ledger-schema-20260813-044338','transport-deadletters-20260813-042738')) {
  "'$dir = Join-Path $repairs $d
  $b = Test-JsonUtf8 (Join-Path $dir '"'progress_ledger.before.json')
  "'$a = Test-JsonUtf8 (Join-Path $dir '"'progress_ledger.after.json')
  "'$mm = Test-JsonUtf8 (Join-Path $dir '"'repair_manifest.json')
  Write-Output (\"{0}: before={1} after={2} manifest={3}\" -f "'$d, $b, $a, $mm)
}
# event cursors
foreach ($d in @('"'parent-replay-incident-20260813-044825','plain-parent-reports-20260813-045304')) {
  "'$dir = Join-Path $repairs $d
  $b = Get-Content -LiteralPath (Join-Path $dir '"'progress_ledger.before.json') -Encoding UTF8 -Raw | ConvertFrom-Json
  "'$a = Get-Content -LiteralPath (Join-Path $dir '"'progress_ledger.after.json') -Encoding UTF8 -Raw | ConvertFrom-Json
  Write-Output (\"{0}: event_cursor before={1} after={2}\" -f "'$d, $b.event_cursor, $a.event_cursor)
}
# quarantine file content spot check
$inc = Join-Path $repairs '"'parent-replay-incident-20260813-044825'
"'$m = Get-Content (Join-Path $inc '"'repair_manifest.json') -Raw | ConvertFrom-Json
"'$badQ = 0
foreach ($f in Get-ChildItem (Join-Path $inc '"'quarantine\\dead_letters') -Filter '*.json') {
  try { "'$v = Get-Content $f.FullName -Encoding UTF8 -Raw | ConvertFrom-Json } catch { Write-Output "  UNPARSABLE quarantine dl: $($f.Name)"; $badQ++; continue }
  if ($v.reason -ne '"'off_table_event') { Write-Output \"  NON off_table reason: "'$($f.Name) -> $($v.reason)"; $badQ++ }
}
Write-Output ("quarantine dead_letters content check: bad={0}/{1}" -f $badQ, @(Get-ChildItem (Join-Path $inc '"'quarantine\\dead_letters') -Filter '*.json').Count)
# plain reports: manifest vs reports.before, and live wrapped reports
"'$p = Join-Path $repairs '"'plain-parent-reports-20260813-045304'
"'$pm = Get-Content (Join-Path $p '"'repair_manifest.json') -Raw | ConvertFrom-Json
"'$rb = @(Get-ChildItem (Join-Path $p '"'reports.before') -Filter '*.bin' | ForEach-Object { "'$_.BaseName })
$pr = @($pm.repaired)
Write-Output ("plain-reports: manifest repaired={0} reports.before on_disk={1} missing={2} extra={3}" -f $pr.Count, $rb.Count, @($pr | Where-Object { $rb -notcontains $_ }).Count, @($rb | Where-Object { $pr -notcontains $_ }).Count)
$badLive = 0
foreach ($id in $pr) {
  $rp = Join-Path $root ("data'"\\reports\\{0}\\report.json\" -f "'$id)
  if (-not (Test-Path $rp)) { Write-Output "  MISSING live report: $id"; $badLive++; continue }
  try { $v = Get-Content $rp -Raw | ConvertFrom-Json } catch { Write-Output "  UNPARSABLE live report: $id"; $badLive++; continue }
  if ($v.packet_id -ne $id) { Write-Output "  WRONG packet_id live report: $id"; $badLive++ }
}
Write-Output ("plain-reports: live wrapped report.json valid {0}/{1}" -f ($pr.Count - $badLive), $pr.Count)
# .bin files are raw text (non-JSON) -> recoverable originals
$nonJson = 0
foreach ($f in Get-ChildItem (Join-Path $p '"'reports.before') -Filter '*.bin') {
  "'$txt = Get-Content $f.FullName -Encoding UTF8 -Raw
  try { $null = $txt | ConvertFrom-Json; $nonJson++ } catch {}
}
Write-Output ("reports.before .bin files that parse as JSON (should be 0): {0}" -f $nonJson)'

