"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$root = '"'E:\\codex-LOOP\\codex-loop-s-f2'
"'$repairs = Join-Path $root '"'data\\repairs'
"'$p = Join-Path $repairs '"'plain-parent-reports-20260813-045304'
"'$pm = Get-Content (Join-Path $p '"'repair_manifest.json') -Raw | ConvertFrom-Json
"'$pr = @($pm.repaired)
$badLive = 0
$sample = $null
foreach ($id in $pr) {
  $rp = Join-Path $root ("data'"\\reports\\{0}\\report.json\" -f "'$id)
  if (-not (Test-Path $rp)) { Write-Output "  MISSING live report: $id"; $badLive++; continue }
  try { $v = Get-Content -LiteralPath $rp -Encoding UTF8 -Raw | ConvertFrom-Json } catch { Write-Output "  UNPARSABLE live report: $id"; $badLive++; continue }
  if ($v.packet_id -ne $id) { Write-Output "  WRONG packet_id live report: $id"; $badLive++ }
  if (-not $sample) { $sample = $v }
}
Write-Output ("plain-reports: live wrapped report.json valid {0}/{1}" -f ($pr.Count - $badLive), $pr.Count)
Write-Output ("sample live report keys: {0}; status={1}; run_id={2}; summary_len={3}" -f (($sample.PSObject.Properties.Name) -join '"','), "'$sample.status, $sample.run_id, $sample.summary.Length)
# after-ledger states for the repaired packets
$a = Get-Content (Join-Path $p '"'progress_ledger.after.json') -Encoding UTF8 -Raw | ConvertFrom-Json
"'$st = @{}
foreach ($id in $pr) { $st[$id] = $a.packets.$id.state }
$stCounts = $st.Values | Group-Object | ForEach-Object { "$($_.Name)=$($_.Count)" }
Write-Output ("plain-reports after-ledger states: {0}" -f ($stCounts -join '"' '))
# incident after-ledger states vs manifest states
"'$inc = Join-Path $repairs '"'parent-replay-incident-20260813-044825'
"'$m = Get-Content (Join-Path $inc '"'repair_manifest.json') -Raw | ConvertFrom-Json
"'$ai = Get-Content (Join-Path $inc '"'progress_ledger.after.json') -Encoding UTF8 -Raw | ConvertFrom-Json
"'$mismatch = 0
foreach ($pid in @($m.selected)) {
  $ms = $m.states.$pid
  $ls = $ai.packets.$pid.state
  if ($ms -ne $ls) { Write-Output "  STATE MISMATCH $pid manifest=$ms ledger=$ls"; $mismatch++ }
}
Write-Output ("incident: manifest states match after-ledger for {0}/{1} selected" -f (@($m.selected).Count - $mismatch), @($m.selected).Count)'

